using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using Aevoria.World;
using Aevoria.Persistence;
static class PlanetaryChecks
{
    static double Deviation(double[] values){double mean=values.Average();return Math.Sqrt(values.Select(x=>(x-mean)*(x-mean)).Average());}
    static int[] Patches(int[] labels,int n){var sizes=new System.Collections.Generic.List<int>();var seen=new bool[labels.Length];for(int i=0;i<labels.Length;i++)if(labels[i]>=0&&!seen[i]){int count=0;var q=new System.Collections.Generic.Queue<int>();q.Enqueue(i);seen[i]=true;while(q.Count>0){int k=q.Dequeue();count++;int x=k%n,z=k/n;for(int d=0;d<4;d++){int j=d==0?(x>0?k-1:-1):d==1?(x<n-1?k+1:-1):d==2?(z>0?k-n:-1):(z<n-1?k+n:-1);if(j>=0&&!seen[j]&&labels[j]==labels[i]){q.Enqueue(j);seen[j]=true;}}}sizes.Add(count);}return sizes.OrderBy(x=>x).ToArray();}
    public static void Run()
    {
        string output=Path.Combine(Environment.GetEnvironmentVariable("AEVORIA_VALIDATION_OUTPUT")??Path.Combine("Docs","Validation","Alpha-v0.0.8"),"Models");Directory.CreateDirectory(output);
        using var summary=new StreamWriter(Path.Combine(output,"geography.csv"));summary.WriteLine("seed,size,seconds,width,landFraction,landComponents,largestLandShare,biomes,minTemperature,maxTemperature,minHeight,maxHeight,riverSegments,lakeCandidates,geologyBytes,acceptedLakes,dryRiverTerminals,seasonallyDryChannels,mountainComponents,largestMountainCells,medianBiomePatchCells,largestBiomePatchCells,temperatureStdDev,rainStdDev,lakeAreaMedianKm2,largestLakeKm2,fingerprint");
        foreach(string seed in new[]{"aevoria-007","shaping-continents"})foreach(var size in new[]{WorldSize.Miniature,WorldSize.Small,WorldSize.Medium,WorldSize.Large,WorldSize.Colossal})
        {
            if(Environment.GetEnvironmentVariable("AEVORIA_PLANET_SEED") is string selectedSeed&&seed!=selectedSeed)continue;
            if(Environment.GetEnvironmentVariable("AEVORIA_PLANET_SIZE") is string selectedSize&&size.ToString()!=selectedSize)continue;
            var timer=Stopwatch.StartNew();var geo=new ProceduralGeography(GenerationSettings.Preset(seed,size));double seconds=timer.Elapsed.TotalSeconds;const int n=129;var land=new bool[n*n];var labels=new int[n*n];var mountains=new int[n*n];var temperatures=new double[n*n];var rainfall=new double[n*n];var biomes=new System.Collections.Generic.HashSet<Biome>();float tMin=100,tMax=-100,hMin=100000,hMax=-100000;
            using(var raster=new StreamWriter(Path.Combine(output,seed+"-"+size+".csv"))){raster.WriteLine("x,z,height,temperature,rain,biome,uplift");for(int z=0;z<n;z++)for(int x=0;x<n;x++){double east=(x/(double)(n-1)-.5)*geo.Configuration.WidthMeters,north=(z/(double)(n-1)-.5)*geo.Configuration.DepthMeters;var s=geo.Sample(new GeoPoint(east,north));if(!float.IsFinite(s.ElevationMeters)||!float.IsFinite(s.Moisture))throw new Exception("Nonfinite planetary sample");int at=z*n+x;land[at]=s.ElevationMeters>geo.SeaLevel;labels[at]=land[at]?(int)s.Biome:-1;mountains[at]=land[at]&&s.ElevationMeters>geo.SeaLevel+geo.Configuration.Terrain.Mountains*.35+240?1:-1;temperatures[at]=s.TemperatureCelsius;rainfall[at]=s.Moisture;if(land[z*n+x]){biomes.Add(s.Biome);tMin=Math.Min(tMin,s.TemperatureCelsius);tMax=Math.Max(tMax,s.TemperatureCelsius);}hMin=Math.Min(hMin,s.ElevationMeters);hMax=Math.Max(hMax,s.ElevationMeters);raster.WriteLine(FormattableString.Invariant($"{x},{z},{s.ElevationMeters},{s.TemperatureCelsius},{s.Moisture},{(int)s.Biome},{geo.Geology.Sample(east,north).Uplift}"));}}
            int landCount=land.Count(x=>x),components=0,largest=0;var seen=new bool[land.Length];for(int i=0;i<land.Length;i++)if(land[i]&&!seen[i]){components++;int count=0;var queue=new System.Collections.Generic.Queue<int>();queue.Enqueue(i);seen[i]=true;while(queue.Count>0){int k=queue.Dequeue();count++;int x=k%n,z=k/n;for(int d=0;d<4;d++){int j=d==0?(x>0?k-1:-1):d==1?(x<n-1?k+1:-1):d==2?(z>0?k-n:-1):(z<n-1?k+n:-1);if(j>=0&&land[j]&&!seen[j]){seen[j]=true;queue.Enqueue(j);}}}largest=Math.Max(largest,count);}
            int dryTerminals=0,seasonallyDry=0;var hydro=geo.Hydrology;for(int i=0;i<hydro.Ground.Length;i++)if(hydro.Receiver[i]>=0&&hydro.Water[i]+.001<hydro.Water[hydro.Receiver[i]])throw new Exception("Uphill drainage after basin breach");for(int i=0;i<hydro.Ground.Length;i++)if(hydro.IsRiver(i)){if(geo.InlandSurfaces.IsSeasonallyDryChannel(i)){seasonallyDry++;continue;}int r=hydro.Receiver[i];bool terminalPool=geo.InlandSurfaces.HasTerminalPool(r)&&hydro.IsRiverWater(hydro.X(r),hydro.Y(r),geo.ElevationAt(hydro.X(r),hydro.Y(r)));if(!hydro.IsRiver(r)&&hydro.Ground[r]>geo.SeaLevel&&!geo.InlandSurfaces.LakeAt(hydro.X(r),hydro.Y(r),out _)&&!terminalPool){dryTerminals++;Console.WriteLine($"DRY END {seed}/{size} river {i} -> {r}, lake {hydro.Lake[r]}, outcome {hydro.OutcomeAt(r)}, cap {geo.InlandSurfaces.HasTerminalPool(r)}, wet {hydro.IsRiverWater(hydro.X(r),hydro.Y(r),geo.ElevationAt(hydro.X(r),hydro.Y(r)))}, climate {geo.Sample(new GeoPoint(hydro.X(i),hydro.Y(i))).Moisture}, area {hydro.CatchmentSquareKilometres(i)}/{hydro.SeasonalCatchmentSquareKilometres}, ground {hydro.Ground[r]}, level {hydro.Water[r]}, at {hydro.X(r)}/{hydro.Y(r)}");}}
            if(dryTerminals!=0)throw new Exception("Dry river outlets");
            var mountainPatches=Patches(mountains,n);var biomePatches=Patches(labels,n);var areas=new System.Collections.Generic.Dictionary<float,double>();var lake=geo.InlandSurfaces.Lakes;for(int i=0;i<lake.Vertices.Count;i+=3){var a=lake.Vertices[i];var b=lake.Vertices[i+1];var c=lake.Vertices[i+2];double area=Math.Abs((b.X-a.X)*(c.Z-a.Z)-(b.Z-a.Z)*(c.X-a.X))*.5/1000000;areas.TryGetValue(a.Level,out double total);areas[a.Level]=total+area;}var lakeAreas=areas.Values.OrderBy(x=>x).ToArray();string fingerprint=WorldRecord.GeographyFingerprint(geo);
            var repeat=new ProceduralGeography(GenerationSettings.Preset(seed,size));if(fingerprint!=WorldRecord.GeographyFingerprint(repeat))throw new Exception("Reconstruction differs "+seed+size);System.Threading.Tasks.Parallel.For(0,512,i=>{double x=(i%32/31.0-.5)*geo.Configuration.WidthMeters,z=(i/32/15.0-.5)*geo.Configuration.DepthMeters;if(geo.ElevationAt(x,z)!=repeat.ElevationAt(x,z))throw new Exception("Thread/query order differs");});
            summary.WriteLine(FormattableString.Invariant($"{seed},{size},{seconds},{geo.Configuration.WidthMeters},{landCount/(double)land.Length},{components},{largest/(double)landCount},{biomes.Count},{tMin},{tMax},{hMin},{hMax},{geo.Hydrology.RiverSegments},{geo.Hydrology.LakeCount},{geo.Geology.FieldBytes},{geo.InlandSurfaces.LakeCount},{dryTerminals},{seasonallyDry},{mountainPatches.Length},{mountainPatches.LastOrDefault()},{biomePatches[biomePatches.Length/2]},{biomePatches.LastOrDefault()},{Deviation(temperatures)},{Deviation(rainfall)},{(lakeAreas.Length>0?lakeAreas[lakeAreas.Length/2]:0)},{lakeAreas.LastOrDefault()},{fingerprint}"));summary.Flush();Console.WriteLine($"PLANET {seed}/{size}: {seconds:0.00}s {geo.Geology.Arrangement}, land {landCount/(double)land.Length:P0}, {components} components, largest {largest/(double)landCount:P0}, {biomes.Count} biomes, temperature {tMin:0}..{tMax:0}, heights {hMin:0}..{hMax:0}, lakes {geo.InlandSurfaces.LakeCount}/{geo.Hydrology.LakeCount}, dry ends {dryTerminals}, climate-supported seasonal channels {seasonallyDry}");
        }
    }
}
